document.addEventListener("DOMContentLoaded", function () {
  const form = document.getElementById("reset_password");

  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();

      const email = form.querySelector('input[name="user"]').value;
      const csrfToken = page_data.csrf_token;

      const payload = {
        user: email
      };

      fetch("/api/method/frappe.core.doctype.user.user.reset_password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          'x-frappe-csrf-token': csrfToken,
        },
        body: JSON.stringify(payload)
      })
      .then(response => response.json())
        .then(data => {
            console.log(data)
          if (data._server_messages) {
             const messages = JSON.parse(data._server_messages);
  const firstMessage = JSON.parse(messages[0]); // Parse again here

  const errorMsg = firstMessage.message || "Something went wrong.";

            Toastify({
              text: `❌ ${errorMsg}`,
              close: true,
              gravity: "top",
              position: "center",
              stopOnFocus: true,
              style: {
                background: "linear-gradient(to right, #ff416c, #ff4b2b)", // red tone
              }
            }).showToast();
          } else {
            Toastify({
              text: "✅ Reset link sent successfully!",
              close: true,
              gravity: "top",
              position: "center",
              stopOnFocus: true,
              style: {
                background: "linear-gradient(to right, #00b09b, #96c93d)",
              }
            }).showToast();
          }
        })
        .catch(error => {
          console.error("Error:", error);
          Toastify({
            text: "⚠️ Network error. Please try again.",
            close: true,
            gravity: "top",
            position: "center",
            stopOnFocus: true,
            style: {
              background: "linear-gradient(to right, #ff416c, #ff4b2b)",
            }
          }).showToast();
        });
    });
  }
});
window.onload = function () {
  if (page_data.user && page_data.user !== "Guest") {
    const urlParams = new URLSearchParams(window.location.search);
    const redirectTo = urlParams.get('redirect-to');

    window.location.href = redirectTo || '/profile';
  }
};
